INSERT INTO suppliers (supplier_id, name, category, city, rating, fssai_certified, payment_terms_days, notes) VALUES
('S01', 'Anand Valley Dairy Cooperative', 'dairy', 'Anand', 4.6, TRUE, 15, 'Main supplier of milk and fresh cream for all four plants. Supplies 70% of our dairy under a 3-year contract that runs to March 2027. Very reliable; never missed a delivery in 2024.'),
('S02', 'Green Meadows Milk Products', 'dairy', 'Karnal', 3.9, TRUE, 30, 'Backup dairy supplier, mainly skimmed milk powder. Fat content ran below specification twice in summer 2025, so every lot is now tested on arrival.'),
('S03', 'Sahyadri Sugars', 'sugar', 'Kolhapur', 4.2, TRUE, 30, 'Sole sugar supplier. Prices are fixed every six months. Also supplies the sucralose and maltitol blend for the sugar-free range.'),
('S04', 'Ratnagiri Fruit Pulp Works', 'fruit', 'Ratnagiri', 4.4, TRUE, 45, 'Alphonso mango pulp, strawberry and raspberry purée. Mango pulp is bought once a year in May and stored frozen. Raspberry purée costs rose 40% in 2025, one reason the Raspberry Sorbet was discontinued.'),
('S05', 'Kashmir Saffron and Nut Traders', 'flavour', 'Srinagar', 3.6, TRUE, 30, 'Saffron, pistachio and almonds. Delivered pistachio with shell fragments in August 2025 (incident QI-2025-07); now on a corrective action plan with an extra sieving step.'),
('S06', 'CocoaCraft Ingredients', 'cocoa', 'Bengaluru', 4.1, TRUE, 30, 'Cocoa powder, chocolate chips and the soy-lecithin chocolate coating for bars and cones.'),
('S07', 'Polypack Containers', 'packaging', 'Daman', 3.4, FALSE, 60, 'Cups, tubs and lids. A batch of 500 ml tub lids did not seal properly in April 2025 (incident QI-2025-03). Food-contact certificate renewal is pending.'),
('S08', 'ConeCraft Wafers', 'packaging', 'Hosur', 4.3, TRUE, 30, 'Wafer cones and cone sleeves, delivered to all plants from its Hosur factory. Cones contain gluten.');
INSERT INTO products (sku, name, category, flavour, pack_size_ml, mrp_inr, unit_cost_inr, launch_date, status, discontinued_on, description) VALUES
('FF-CUP-VAN-100', 'Classic Vanilla Cup', 'cup', 'vanilla', 100, 30, 13.0, '2019-03-01', 'active', NULL, 'Our best-known product: a 100 ml cup of vanilla ice cream made with fresh cream and real vanilla.'),
('FF-CUP-CHO-100', 'Double Chocolate Cup', 'cup', 'chocolate', 100, 35, 15.0, '2019-03-01', 'active', NULL, 'Chocolate ice cream with chocolate chips, in a 100 ml cup.'),
('FF-CUP-BSC-100', 'Butterscotch Crunch Cup', 'cup', 'butterscotch', 100, 35, 14.5, '2020-02-01', 'active', NULL, 'Butterscotch ice cream with caramelised cashew crunch, in a 100 ml cup. Contains tree nuts.'),
('FF-CON-CHO-120', 'Choco Fudge Cone', 'cone', 'chocolate', 120, 50, 22.0, '2019-04-01', 'active', NULL, 'Wafer cone filled with chocolate ice cream and a fudge core, topped with chocolate coating.'),
('FF-CON-STR-120', 'Strawberry Swirl Cone', 'cone', 'strawberry', 120, 50, 21.0, '2021-03-01', 'active', NULL, 'Wafer cone with vanilla and strawberry swirl ice cream.'),
('FF-CON-PST-120', 'Pista Royale Cone', 'cone', 'pistachio', 120, 60, 27.0, '2025-03-01', 'active', NULL, 'Premium pistachio cone with roasted pistachio pieces. Launched in March 2025. Contains tree nuts.'),
('FF-STK-MNG-70', 'Mango Duet Stick', 'stick', 'mango', 70, 25, 10.0, '2020-04-01', 'active', NULL, 'Alphonso mango ice cream on a stick with a mango sorbet coating.'),
('FF-STK-ORG-60', 'Orange Bar', 'stick', 'orange', 60, 10, 3.8, '2018-04-01', 'active', NULL, 'Low-price orange ice lolly for general trade. Our highest-volume SKU.'),
('FF-STK-CHO-70', 'Choco Bar', 'stick', 'chocolate', 70, 30, 12.5, '2018-04-01', 'active', NULL, 'Vanilla ice cream on a stick with a crackling chocolate coating.'),
('FF-TUB-VAN-500', 'Classic Vanilla Tub', 'tub', 'vanilla', 500, 140, 62.0, '2019-03-01', 'active', NULL, 'Family pack of Classic Vanilla, 500 ml.'),
('FF-TUB-BSC-750', 'Butterscotch Family Tub', 'tub', 'butterscotch', 750, 220, 98.0, '2020-10-01', 'active', NULL, '750 ml butterscotch tub for families and parties. Contains tree nuts.'),
('FF-TUB-CCH-500', 'Cookies and Cream Tub', 'tub', 'cookies and cream', 500, 180, 81.0, '2022-02-01', 'active', NULL, 'Vanilla ice cream with chocolate cookie pieces, 500 ml. Contains gluten.'),
('FF-TUB-SFV-500', 'Sugar-Free Vanilla Tub', 'tub', 'vanilla', 500, 200, 95.0, '2025-01-01', 'active', NULL, 'Vanilla ice cream sweetened with sucralose and maltitol, launched in January 2025 for diabetic and health-conscious buyers.'),
('FF-KUL-MLI-60', 'Malai Kulfi', 'kulfi', 'malai', 60, 30, 12.0, '2019-04-01', 'active', NULL, 'Traditional slow-cooked milk kulfi on a stick.'),
('FF-KUL-KES-60', 'Kesar Pista Kulfi', 'kulfi', 'saffron pistachio', 60, 40, 17.5, '2019-04-01', 'active', NULL, 'Kulfi flavoured with Kashmiri saffron and pistachio. Contains tree nuts.'),
('FF-KUL-MNG-60', 'Mango Kulfi', 'kulfi', 'mango', 60, 35, 14.5, '2021-04-01', 'active', NULL, 'Kulfi made with Alphonso mango pulp.'),
('FF-SOR-LMN-100', 'Lemon Mint Sorbet', 'sorbet', 'lemon mint', 100, 45, 17.0, '2024-10-01', 'active', NULL, 'Vegan, dairy-free lemon and mint sorbet, launched in October 2024.'),
('FF-SOR-RSP-100', 'Raspberry Sorbet', 'sorbet', 'raspberry', 100, 50, 20.0, '2023-03-01', 'discontinued', '2025-06-30', 'Vegan raspberry sorbet. Discontinued at the end of June 2025 after raspberry purée costs rose and sales stayed low.');
