INSERT INTO promotions (promo_id, name, sku, channel, region_id, start_date, end_date, discount_pct, notes) VALUES
('PR-2024-01', 'Summer Cone Fest 2024', 'FF-CON-CHO-120', 'modern_trade', NULL, '2024-04-01', '2024-05-31', 15.0, 'Buy 2 get 1 free on Choco Fudge Cones in supermarkets nationwide. Lifted cone volume by about 30% in April and May.'),
('PR-2024-02', 'Mango Mania 2024', 'FF-KUL-MNG-60', 'general_trade', 'WEST', '2024-05-01', '2024-06-30', 10.0, 'Mango Kulfi at a 10% trade discount in western corner shops, timed with the Alphonso season. Free branded freezer stickers for shops that stocked 2 cartons.'),
('PR-2024-03', 'Diwali Family Tub Offer', 'FF-TUB-BSC-750', 'modern_trade', NULL, '2024-10-15', '2024-11-10', 18.0, 'Festive price-off on the Butterscotch Family Tub for Diwali gatherings, supported by in-store sampling.'),
('PR-2024-04', 'Sorbet Launch Sampling', 'FF-SOR-LMN-100', 'modern_trade', 'SOUTH', '2024-10-01', '2024-12-31', 12.0, 'Launch support for Lemon Mint Sorbet in Bengaluru and Chennai supermarkets: 12% off plus 40,000 free sample spoons.'),
('PR-2025-01', 'Quick Commerce Midnight Deals', 'FF-TUB-VAN-500', 'quick_commerce', NULL, '2025-03-01', '2025-06-30', 20.0, '20% off Classic Vanilla Tubs ordered between 10 pm and 2 am on delivery apps. The largest promotion of 2025; it needed CFO sign-off.'),
('PR-2025-02', 'Summer Cone Fest 2025', 'FF-CON-PST-120', 'modern_trade', NULL, '2025-04-01', '2025-05-31', 15.0, 'Buy 2 get 1 free, this year on the new Pista Royale Cone to drive trial after its March 2025 launch.'),
('PR-2025-03', 'Kulfi Nights North', 'FF-KUL-KES-60', 'general_trade', 'NORTH', '2025-05-01', '2025-06-30', 8.0, 'Extra margin for northern corner shops that kept Kesar Pista Kulfi in the front freezer.'),
('PR-2025-04', 'Sugar-Free Awareness Month', 'FF-TUB-SFV-500', 'modern_trade', NULL, '2025-11-01', '2025-11-30', 10.0, 'Tie-up with diabetes awareness month, with 10% off the Sugar-Free Vanilla Tub and pharmacy-aisle displays.'),
('PR-2025-05', 'HoReCa Dessert Partner', 'FF-CUP-CHO-100', 'horeca', 'SOUTH', '2025-07-01', '2025-09-30', 12.0, 'Volume discount for southern restaurants that serve Double Chocolate Cups as a dessert option.');
INSERT INTO quality_incidents (incident_id, batch_id, reported_on, severity, category, description, root_cause, corrective_action, status) VALUES
('QI-2024-01', 'B2405-P04-06', '2024-05-14', 'medium', 'temperature_excursion', 'Ice crystals and shrinkage found in Kesar Pista Kulfi delivered to Bengal Frost Agencies in Kolkata.', 'A reefer truck compressor failed on the route from Kalyani; the data logger showed -9 °C for 3 hours.', 'The batch was destroyed. Reefers on routes longer than 8 hours now carry a backup compressor.', 'closed'),
('QI-2024-02', 'B2404-P01-01', '2024-04-22', 'low', 'texture', 'Soggy wafer cones reported by supermarkets in Delhi.', 'Cones were filled before the chocolate barrier coating had set, so moisture reached the wafer.', 'Coating cure time on the Sonipat cone line raised from 40 to 60 seconds.', 'closed'),
('QI-2024-03', 'B2406-P03-12', '2024-06-05', 'high', 'foreign_matter', 'A consumer in Chennai found a piece of blue plastic in an Orange Bar.', 'A worn scraper blade on the Hosur stick moulding line was shedding plastic.', 'Batch withdrawn from the market. Scraper blades are now metal-detectable and inspected every shift.', 'closed'),
('QI-2024-04', 'B2409-P02-09', '2024-09-11', 'low', 'labelling', 'Raspberry Sorbet packs printed with the wrong best-before date format.', 'The date coder template was not updated after a software upgrade.', 'Template change control added; packs were over-stickered before dispatch.', 'closed'),
('QI-2024-05', 'B2412-P01-16', '2024-12-03', 'medium', 'packaging', 'Dented Classic Vanilla Tubs arriving at Capital Cold Distributors.', 'Cartons were stacked 8 high in the cold room instead of the maximum of 5.', 'Stacking limits painted on cold room floors and added to the warehouse checklist.', 'closed'),
('QI-2025-01', 'B2502-P03-09', '2025-02-18', 'high', 'allergen', 'Lemon Mint Sorbet, sold as vegan and nut-free, tested positive for pistachio protein.', 'The Hosur line ran Kesar Pista Kulfi before the sorbet and the allergen swab after cleaning was skipped.', 'Voluntary recall of the batch; FSSAI was notified within 24 hours. Swab results must now be recorded before the line is released.', 'closed'),
('QI-2025-02', 'B2503-P02-06', '2025-03-09', 'low', 'texture', 'Classic Vanilla Cups from Pune tasted icy and less creamy.', 'Skimmed milk powder from Green Meadows Milk Products was below fat specification.', 'Incoming milk powder is now tested for fat content on every lot.', 'closed'),
('QI-2025-03', 'B2504-P02-16', '2025-04-16', 'medium', 'packaging', 'Lids on Cookies and Cream Tubs popping off, leading to freezer burn.', 'A batch of 500 ml tub lids from Polypack Containers was 0.3 mm too wide.', 'Lids are sampled on arrival with a go/no-go gauge. Polypack issued a credit for the faulty lot.', 'closed'),
('QI-2025-04', 'B2505-P01-13', '2025-05-27', 'medium', 'temperature_excursion', 'Mango Duet Sticks melted and refroze at Lucknow Ice Traders during a power cut in a heatwave.', 'The distributor''s cold room had no generator backup and lost power for 6 hours.', 'Stock destroyed at the distributor''s cost. Lucknow Ice Traders must install a generator to stay tier B.', 'closed'),
('QI-2025-05', 'B2506-P03-03', '2025-06-12', 'low', 'texture', 'Strawberry swirl not visible in some Strawberry Swirl Cones.', 'The ripple pump on the Hosur cone line was running at half speed.', 'Pump speed is now logged at the start of every run.', 'closed'),
('QI-2025-06', 'B2507-P01-08', '2025-07-08', 'low', 'labelling', 'Malai Kulfi wrappers missing the Hindi product name.', 'The printer used an old artwork file.', 'Artwork files are now checked against the approved list before every print run.', 'closed'),
('QI-2025-07', 'B2508-P01-02', '2025-08-21', 'high', 'foreign_matter', 'Hard shell fragments found in Pista Royale Cones by two consumers in Delhi.', 'Pistachio from Kashmir Saffron and Nut Traders contained shell pieces.', 'Batch withdrawn. The supplier added a sieving step and is on a corrective action plan; we X-ray every nut lot.', 'closed'),
('QI-2025-08', 'B2511-P02-16', '2025-11-06', 'medium', 'labelling', 'Sugar-Free Vanilla Tub packs missing the statutory laxative-effect warning for maltitol.', 'A new pack design went to print without regulatory review.', 'Batch on hold while packs are re-labelled. Regulatory review added as a mandatory artwork step.', 'open');
INSERT INTO documents (doc_id, title, category, owner, updated_on, body_md) VALUES
('cold-chain-sop', 'Cold Chain SOP', 'operations', 'Head of Supply Chain', '2025-02-10', '# Cold Chain SOP
